// Smart Scanner: Finds the specific JSON block containing 'api_path'
// This ignores the first JSON block if it's just a repetition of the input.

const inputItem = items[0].json;
const rawText = inputItem.output || inputItem.text || inputItem.response || JSON.stringify(inputItem);

// Find ALL potential JSON objects (non-greedy match)
const potentialJsonBlocks = rawText.match(/\{[\s\S]*?\}/g) || [];

let validPayload = null;

for (const block of potentialJsonBlocks) {
  try {
    const parsed = JSON.parse(block);
    // CRITICAL CHECK: Does this block have the keys we actually need?
    if (parsed.api_path && parsed.method) {
      validPayload = parsed;
      break; // Found it!
    }
  } catch (e) {
    continue; // Skip invalid JSON or plain text wrapped in braces
  }
}

if (!validPayload) {
  throw new Error("CRITICAL: Agent 2 output text, but no JSON block contained 'api_path' and 'method'. Raw: " + rawText);
}

return {
  json: {
    api_path: validPayload.api_path,
    method: validPayload.method
  }
};
